#include <stdio.h>

int main(void)
{
    int pairs = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = i + 1; j < 4; j++) {
            pairs++;
        }
    }
    printf("%d\n", pairs);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 16;
    int steps = 0;
    while (n > 1) {
        n /= 2;
        steps++;
    }
    printf("%d\n", steps);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int values[] = {12, 24, 36};
    int checks = 0;
    for (int i = 0; i < 3; i++) {
        checks++;
        if (values[i] == 36) {
            break;
        }
    }
    printf("%d\n", checks);
    return 0;
}
